-- Milestone 1: identity, guest sessions, and player progress.
-- IDs are generated by the API so the schema works on Postgres and PGlite.

CREATE TABLE IF NOT EXISTS accounts (
  id text PRIMARY KEY,
  email text NOT NULL,
  password_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS accounts_email_lower_unique ON accounts (lower(email));

CREATE TABLE IF NOT EXISTS profiles (
  id text PRIMARY KEY,
  account_id text UNIQUE REFERENCES accounts(id) ON DELETE CASCADE,
  display_name text NOT NULL DEFAULT 'PlayerOne',
  country text NOT NULL DEFAULT 'US',
  avatar_hue integer NOT NULL DEFAULT 266,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS profiles_account_idx ON profiles (account_id);

CREATE TABLE IF NOT EXISTS guest_sessions (
  id text PRIMARY KEY,
  token_hash text NOT NULL UNIQUE,
  profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);

CREATE INDEX IF NOT EXISTS guest_sessions_profile_idx ON guest_sessions (profile_id);

CREATE TABLE IF NOT EXISTS auth_sessions (
  id text PRIMARY KEY,
  token_hash text NOT NULL UNIQUE,
  account_id text NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);

CREATE INDEX IF NOT EXISTS auth_sessions_account_idx ON auth_sessions (account_id);

CREATE TABLE IF NOT EXISTS player_state (
  profile_id text PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE,
  revision integer NOT NULL DEFAULT 0,
  document jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS player_progress (
  profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  game_id text NOT NULL,
  plays integer NOT NULL DEFAULT 0 CHECK (plays >= 0),
  best numeric,
  coins_earned integer NOT NULL DEFAULT 0,
  last_played_at timestamptz,
  PRIMARY KEY (profile_id, game_id)
);

CREATE INDEX IF NOT EXISTS player_progress_game_idx ON player_progress (game_id);
